  function clientDashboard(){return `${pageHead('Исполнение охраны','Только подтвержденные данные по вашим объектам, постам, обходам и опубликованным событиям.',btn('Скачать отчет','download','primary'))}<div class="grid cols-4">${metric('Покрытие сегодня','99.1%','+0.5 п.п.','shield')}${metric('Посты сейчас','12 / 12','все закрыты','check')}${metric('Обходы','28 / 29','1 требует внимания','route')}${metric('Опубликованные инциденты','2','за 30 дней','alert')}</div><div class="grid cols-2 section"><div class="card"><div class="card-head"><h3>Мои объекты</h3><span class="meta">3 объекта</span></div>${mini('building','БЦ «Север»','4 / 4 поста · 100%','success')}${mini('building','Офис «Арма»','2 / 2 поста · 100%','success')}${mini('building','Паркинг «Север»','1 / 1 пост · 96.7% за месяц','warning')}</div><div class="card"><div class="card-head"><h3>Последние события</h3></div><div class="timeline"><div class="time-row"><strong>08:00 — все дневные посты закрыты</strong><p>БЦ «Север»</p></div><div class="time-row"><strong>07:18 — опубликовано происшествие</strong><p>Медицинский случай · INC-2026-090</p></div><div class="time-row"><strong>Вчера 21:00 — отчет опубликован</strong><p>Сентябрь 2026 · версия 1</p></div></div></div></div>`}
  function clientFacilities(){return `${pageHead('Мои объекты','Объекты, включенные в доступ представителя заказчика.')}<div class="grid cols-3">${[['БЦ «Север»','Москва · 4 поста','100%','success'],['Офис «Арма»','Москва · 2 поста','100%','success'],['Паркинг «Север»','Москва · 1 пост','96.7%','warning']].map(x=>`<div class="card" data-open="client:facility" style="cursor:pointer"><div class="card-head"><div class="mini-icon">${ico('building')}</div><h3>${x[0]}</h3></div><p style="color:var(--muted)">${x[1]}</p><div style="display:flex;justify-content:space-between;align-items:center"><strong style="font-size:22px">${x[2]}</strong>${pill(x[3]==='success'?'Норма':'Внимание',x[3])}</div></div>`).join('')}</div>`}
  function clientFacility(){return `${pageHead('БЦ «Север»','Доказательства исполнения охраны по объекту.',btn('Отчет по объекту','download'))}<div class="grid cols-4">${metric('Посты сейчас','4 / 4','100%','shield')}${metric('Обходы сегодня','9 / 9','100%','route')}${metric('NO_SHOW','0','за 30 дней','check')}${metric('Инциденты','1','опубликован','alert')}</div><div class="grid cols-2 section"><div class="card"><div class="card-head"><h3>Покрытие постов</h3></div>${mini('shield','КПП-1','Закрыт · check-in 07:51','success')}${mini('shield','Холл','Закрыт · check-in 07:53','success')}${mini('shield','Паркинг','Закрыт · check-in 07:48','success')}${mini('shield','Периметр','Закрыт · check-in 07:55','success')}</div><div class="card"><div class="card-head"><h3>Обходы</h3></div>${mini('route','Утренний обход','3 / 3 точек · 08:22','success')}${mini('route','Периметр','4 / 4 точек · 06:55','success')}${mini('route','Вечерний обход','Запланирован 18:00','info')}</div></div>`}
  function coverageScreen(){return `${pageHead('Покрытие постов','План и фактическое закрытие постов по объектам и периодам.',btn('Экспорт PDF','download','primary'))}<div class="card"><div class="card-head"><h3>Сентябрь 2026</h3><span class="meta">99.1% общее покрытие</span></div><div class="chart">${['1','5','10','15','20','25','29'].map((d,i)=>`<div class="bar ${i===3?'alt':'good'}" style="height:${[92,96,99,91,98,100,100][i]}%" data-label="${d} сен"></div>`).join('')}</div></div><div class="table-wrap section"><table class="data-table"><thead><tr><th>Объект</th><th>План, ч</th><th>Факт, ч</th><th>NO_SHOW</th><th>Покрытие</th></tr></thead><tbody><tr><td><strong>БЦ «Север»</strong></td><td>2 784</td><td>2 784</td><td>0</td><td>${pill('100%','success')}</td></tr><tr><td><strong>Офис «Арма»</strong></td><td>1 392</td><td>1 386</td><td>0</td><td>${pill('99.6%','success')}</td></tr><tr><td><strong>Паркинг «Север»</strong></td><td>696</td><td>673</td><td>1</td><td>${pill('96.7%','warning')}</td></tr></tbody></table></div>`}
  function clientIncidents(){return `${pageHead('Опубликованные происшествия','Только сведения, разрешенные к публикации заказчику.')}<div class="grid cols-2"><div class="card" data-open="client:incident" style="cursor:pointer"><div class="card-head"><h3>INC-2026-090</h3>${pill('CRITICAL','danger')}</div><strong>Медицинский случай</strong><p style="color:var(--muted);font-size:11px">БЦ «Север» · 29.09 · 07:18</p>${pill('PUBLISHED','info')}</div><div class="card"><div class="card-head"><h3>INC-2026-074</h3>${pill('MEDIUM','warning')}</div><strong>Техническая неисправность двери</strong><p style="color:var(--muted);font-size:11px">Офис «Арма» · 18.09 · 16:44</p>${pill('CLOSED','success')}</div></div>`}
  function clientIncident(){return `${pageHead('INC-2026-090','Опубликованная версия происшествия · БЦ «Север»',btn('Скачать PDF','download'))}<div class="detail-hero"><div class="detail-avatar">!</div><div><h2>Медицинский случай на объекте</h2><p>29 сентября 2026 · 07:18–07:36</p></div><div class="detail-actions">${pill('CLOSED','success')}</div></div><div class="grid cols-2"><div class="card"><div class="card-head"><h3>Что произошло</h3></div><p>На объекте сотруднику посетителя потребовалась медицинская помощь. Охрана вызвала скорую помощь и обеспечила доступ бригады к месту происшествия.</p><div class="notice success">${ico('check')}<div>Действия по инструкции выполнены. Событие закрыто руководителем объекта.</div></div></div><div class="card"><div class="card-head"><h3>Хронология</h3></div><div class="timeline"><div class="time-row"><strong>07:18 Зафиксировано</strong><p>Пост КПП-1</p></div><div class="time-row"><strong>07:20 Вызвана помощь</strong><p>Ответственное лицо уведомлено</p></div><div class="time-row"><strong>07:36 Событие завершено</strong><p>Итог зафиксирован</p></div></div></div></div>`}
  function clientReports(kind){if(kind==='reports')return `${pageHead('Отчеты','Опубликованные версии отчетов, доступные по вашим объектам.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Отчет</th><th>Период</th><th>Версия</th><th>Опубликован</th><th>Статус</th></tr></thead><tbody>${row('Ежемесячный отчет','Сентябрь 2026',['01–29.09','v1','28.09 21:00',pill('NEW','info')],'client:report')}${row('Ежемесячный отчет','Август 2026',['01–31.08','v2','01.09 10:12',pill('ACKNOWLEDGED','success')],'client:report')}</tbody></table></div>`; return `${pageHead('Отчет за сентябрь 2026','Версия 1 · опубликован 28.09.2026 21:00',`${btn('PDF','download','primary')}${btn('Подтвердить ознакомление','check')}`)}<div class="grid cols-4">${metric('Покрытие','99.1%','все объекты','shield')}${metric('Часов','4 843','факт','clock')}${metric('Обходы','118 / 120','98.3%','route')}${metric('Инциденты','2','опубликовано','alert')}</div><div class="card section"><div class="card-head"><h3>Сводка исполнения</h3></div><div class="chart">${['Нед 1','Нед 2','Нед 3','Нед 4'].map((d,i)=>`<div class="bar good" style="height:${[96,98,94,99][i]}%" data-label="${d}"></div>`).join('')}</div></div>`}
  function clientAck(){return `${pageHead('Подтверждение ознакомления','Фиксация факта просмотра опубликованной версии отчета.')}<div class="card" style="max-width:720px;margin:auto"><div class="card-head"><div class="mini-icon success">${ico('check')}</div><h3>Отчет за сентябрь 2026 · версия 1</h3></div><p style="color:var(--muted)">Подтверждая ознакомление, вы фиксируете просмотр именно этой опубликованной версии. Содержимое опубликованной версии не изменяется.</p><label style="display:flex;gap:10px;align-items:flex-start;margin:18px 0"><input type="checkbox" checked><span>Я ознакомился с отчетом и подтверждаю получение опубликованной версии.</span></label>${btn('Подтвердить','check','primary')}</div>`}
  function clientProfile(){return `${pageHead('Профиль','Контактные данные, MFA и доступные объекты.')}<div class="grid cols-2"><div class="card"><div class="detail-hero" style="margin:0;border:0;padding:0"><div class="detail-avatar">АС</div><div><h2>Анна Смирнова</h2><p>Представитель заказчика</p></div></div><div class="section"><dl class="kv"><dt>Email</dt><dd>a.smirnova@sever.ru</dd><dt>Телефон</dt><dd>+7 999 700-11-22</dd><dt>MFA</dt><dd>${pill('Включено','success')}</dd></dl></div></div><div class="card"><div class="card-head"><h3>Доступ</h3></div>${mini('building','БЦ «Север»','Покрытие, обходы, отчеты','success')}${mini('building','Офис «Арма»','Покрытие, обходы, отчеты','success')}${mini('building','Паркинг «Север»','Покрытие, обходы, отчеты','success')}</div></div>`}
  function renderClient(id){if(id==='login'||id==='mfa')return authScreen('client',id);let c=id==='dashboard'?clientDashboard():id==='facilities'?clientFacilities():id==='facility'?clientFacility():id==='coverage'?coverageScreen():id==='incidents'?clientIncidents():id==='incident'?clientIncident():id==='reports'||id==='report'?clientReports(id):id==='ack'?clientAck():clientProfile();return shell('client',id,c)}
